mapper.select:
select inv_aim from( SELECT a.inv_aim,row_number() over() rownum
FROM BOK_VAL_SCHEME_DETAIL_SPECIAL a
WHERE a.scheme_id = #{schemeId,jdbcType=VARCHAR}
AND a.Finprod_Id = #{finprodid,jdbcType=VARCHAR}
AND #{tradeDate,jdbcType=DATE} >= a.vdate
AND coalesce(a.mdate,to_date('2099-12-31','yyyy-mm-dd')) >= #{tradeDate,jdbcType=DATE}
) where rownum = 1
